style.css:
body, html {
    background-color: black !important;
    color: white !important;
}

input[type="text"], input[type="search"], textarea {
    background-color: black !important;
    color: white !important;
    border: 1px solid white !important;
}

input[type="submit"], button {
    background-color: black !important;
    color: white !important;
    border: 1px solid white !important;
}

a, span, div {
    color: white !important;
}

[role="listitem"] {
    background-color: black !important;
    color: white !important;
    border: 1px solid white !important;
}
